#define MAX_ITERATIONS 5

vec2 hilbertPos(int n, int i) {
    vec2 pos = vec2(0.0);
    for (int j = 0; j < n; j++) {
        int s = (i >> (2*j)) & 3;
        float size = float(1 << j);

        if (s == 0) {
            float temp = pos.x;
            pos.x = pos.y;
            pos.y = temp;
        } else if (s == 1) {
            pos.y += size;
        } else if (s == 2) {
            pos.x += size;
            pos.y += size;
        } else if (s == 3) {
            float temp = size - 1.0 - pos.x;
            pos.x = size - 1.0 - pos.y;
            pos.y = temp;
            pos.x += size;
        }
    }

    float scale = float(1 << n);
    vec2 normalized = pos / scale;
    return normalized * 0.8 + 0.1; // Scale and center
}

float drawSegment(vec2 uv, vec2 a, vec2 b, float thickness) {
    vec2 pa = uv - a;
    vec2 ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    float d = length(pa - ba * h);
    return smoothstep(thickness, 0.0, d);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord/iResolution.xy;
    float aspect = iResolution.x/iResolution.y;
    if (aspect > 1.0) {
        uv.x = (uv.x - 0.5) * aspect + 0.5;
    } else {
        uv.y = (uv.y - 0.5) / aspect + 0.5;
    }

    // Draw debug grid (made fainter)
    vec2 gridUV = fract(uv * 8.0);
    float grid = step(0.98, gridUV.x) + step(0.98, gridUV.y);
    fragColor = vec4(vec3(grid * 0.1), 1.0);

    int totalPoints = 1 << (MAX_ITERATIONS * 2);
    float pointSize = 0.006;
    float lineThickness = 0.001;

    // Get luma value from input image
    vec4 color = texture(iChannel0, uv);
    float luma = dot(color.rgb, vec3(0.299, 0.587, 0.114));

    // Adjust pointSize and lineThickness based on luma
    pointSize *= luma * 2.0; // Adjust the multiplier as needed
    lineThickness *= luma * 20.0; // Adjust the multiplier as needed

    // Draw the curve segments
    for(int i = 1; i < totalPoints; i++) {
        vec2 curr = hilbertPos(MAX_ITERATIONS, i);
        vec2 prev = hilbertPos(MAX_ITERATIONS, i-1);

        vec2 mid = vec2(curr.x, prev.y);
        float hline = drawSegment(uv, prev, mid, lineThickness);
        float vline = drawSegment(uv, mid, curr, lineThickness);
        float line = max(hline, vline);
        fragColor = mix(fragColor, vec4(0.7), line);
    }
